import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase, transaction } from './db.ts';
import {
  HEARTBEAT_STALE_MS,
  findJobRowByKey,
  getJob,
  insertJob,
  listJobs,
  toJob,
  type Job,
} from './jobs.ts';

const MAX_BODY_BYTES = 64 * 1024;
const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

interface FieldError {
  field: string;
  message: string;
}

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: Record<string, unknown> = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error });
}

function sendMethodNotAllowed(res: ServerResponse, allowed: string[]): void {
  res.setHeader('allow', allowed.join(', '));
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Use ${allowed.join(' or ')}.`);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function intField(obj: Record<string, unknown>, name: keyof Payload, min: number, max: number, def: number, errors: FieldError[]): number {
  if (!Object.hasOwn(obj, name) || obj[name] === undefined) return def;
  const v = obj[name];
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    errors.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return def;
  }
  return v;
}

/** Validates a parsed body. Returns the payload with defaults applied, or the field errors. */
function validatePayload(body: Record<string, unknown>): { payload: Payload } | { errors: FieldError[] } {
  const errors: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) errors.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  if (typeof body.input !== 'string') {
    errors.push({ field: 'input', message: 'is required and must be a string' });
  } else if (body.input.length < 1 || body.input.length > 1000) {
    errors.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  } else if (body.input.trim().length === 0) {
    errors.push({ field: 'input', message: 'must not be only whitespace' });
  } else {
    input = body.input;
  }

  const steps = intField(body, 'steps', 1, 20, 5, errors);
  const failAttempts = intField(body, 'failAttempts', 0, 5, 0, errors);

  if (errors.length > 0) return { errors };
  return { payload: { input, steps, failAttempts } };
}

function sameJobPayload(row: { input: string; steps: number; fail_attempts: number }, p: Payload): boolean {
  return row.input === p.input && row.steps === p.steps && row.fail_attempts === p.failAttempts;
}

async function handleCreateJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const errors: FieldError[] = [];

  const keyHeader = req.headers['idempotency-key'];
  let idempotencyKey: string | null = null;
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && KEY_PATTERN.test(keyHeader)) idempotencyKey = keyHeader;
    else errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  let parsed: unknown;
  if (tooLarge) {
    errors.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
  } else if (mediaType !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else {
    try {
      parsed = JSON.parse(text);
    } catch {
      errors.push({ field: 'body', message: 'is not valid JSON' });
    }
  }
  if (errors.length === 0 && (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed))) {
    errors.push({ field: 'body', message: 'must be a JSON object' });
  }
  if (errors.length > 0) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
    return;
  }

  const result = validatePayload(parsed as Record<string, unknown>);
  if ('errors' in result) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', result.errors);
    return;
  }
  const payload = result.payload;

  const outcome = transaction(db, (): { status: number; job: Job } | { conflict: true } => {
    if (idempotencyKey !== null) {
      const existing = findJobRowByKey(db, idempotencyKey);
      if (existing) {
        if (!sameJobPayload(existing, payload)) return { conflict: true };
        return { status: 200, job: toJob(existing) };
      }
    }
    return { status: 201, job: insertJob(db, { ...payload, idempotencyKey }) };
  });

  if ('conflict' in outcome) {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different request body.');
    return;
  }
  sendJson(res, outcome.status, outcome.job);
}

function isWorkerUp(conn: DatabaseSync): boolean {
  const row = conn.prepare(`SELECT ts FROM heartbeat WHERE name = 'worker'`).get() as { ts: number } | undefined;
  return row !== undefined && Date.now() - row.ts <= HEARTBEAT_STALE_MS;
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') return sendMethodNotAllowed(res, ['GET']);
    return sendJson(res, 200, { status: 'ok', worker: isWorkerUp(db) ? 'up' : 'down' });
  }

  if (pathname === '/') {
    if (method !== 'GET') return sendMethodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: listJobs(db) });
    if (method === 'POST') return handleCreateJob(req, res);
    return sendMethodNotAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return sendMethodNotAllowed(res, ['GET']);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const job = getJob(db, id);
    if (!job) return sendError(res, 404, 'not_found', 'No such job.');
    return sendJson(res, 200, job);
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

let stopping = false;
function shutdown(): void {
  if (stopping) return;
  stopping = true;
  server.closeAllConnections();
  server.close(() => {
    db.close();
    process.exit(0);
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

